create extension if not exists btree_gist;
create type public.user_role as enum ('STUDENT','INTERVIEWER','ADMIN');
create type public.interview_state as enum ('NOT_ELIGIBLE','ELIGIBLE_NOT_BOOKED','BOOKED','COMPLETED_PENDING_RESULT','PASSED','FAILED','RETAKE_REQUIRED','RETAKE_BOOKED','CANCELLED','NO_SHOW','BADGE_EARNED','NULLIFIED');
create type public.slot_status as enum ('OPEN','BOOKED','BLOCKED','EXPIRED');
create table users(id uuid primary key default gen_random_uuid(),auth_user_id uuid unique,role user_role not null,full_name text not null,email text unique not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table track_badges(id uuid primary key default gen_random_uuid(),name text unique not null,track_name text not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table students(id uuid primary key references users(id),student_code text unique not null,badge_id uuid references track_badges(id),state interview_state not null default 'NOT_ELIGIBLE',timezone text not null default 'Asia/Kolkata',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table interviewers(id uuid primary key references users(id),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table required_skills(id uuid primary key default gen_random_uuid(),badge_id uuid not null references track_badges(id),skill_code text not null,required_level int not null check(required_level>0),unique(badge_id,skill_code));
create table student_skills(id uuid primary key default gen_random_uuid(),student_id uuid not null references students(id),skill_code text not null,verified_level int not null,verified_at timestamptz,unique(student_id,skill_code));
create table interviewer_availability(id uuid primary key default gen_random_uuid(),interviewer_id uuid not null references interviewers(id),starts_at timestamptz not null,ends_at timestamptz not null,blocked boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at),exclude using gist(interviewer_id with =,tstzrange(starts_at,ends_at,'[)') with &&) where(not blocked));
create table interview_slots(id uuid primary key default gen_random_uuid(),availability_id uuid not null references interviewer_availability(id),interviewer_id uuid not null references interviewers(id),starts_at timestamptz not null,ends_at timestamptz not null,status slot_status not null default 'OPEN',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at),unique(interviewer_id,starts_at,ends_at));
create table interview_bookings(id uuid primary key default gen_random_uuid(),student_id uuid not null references students(id),slot_id uuid not null references interview_slots(id),attempt_no int not null,active boolean not null default true,status interview_state not null default 'BOOKED',idempotency_key text not null unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(slot_id),unique(student_id,attempt_no));
create unique index one_active_booking_per_student on interview_bookings(student_id) where active;
create index slots_open_start_idx on interview_slots(status,starts_at);create index bookings_student_idx on interview_bookings(student_id,created_at desc);
create table interview_results(id uuid primary key default gen_random_uuid(),booking_id uuid unique not null references interview_bookings(id),outcome text not null check(outcome in('PASS','FAIL','RETAKE LATER')),feedback text not null,internal_notes text,submitted_by uuid not null references interviewers(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table retake_requests(id uuid primary key default gen_random_uuid(),student_id uuid not null references students(id),prior_booking_id uuid not null references interview_bookings(id),status text not null,eligible_from timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table malpractice_cases(id uuid primary key default gen_random_uuid(),student_id uuid not null references students(id),reason text not null,evidence_reference text not null,status text not null default 'ALLEGED' check(status in('ALLEGED','VERIFIED','REJECTED')),decided_by uuid references users(id),decided_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table badge_status_history(id uuid primary key default gen_random_uuid(),student_id uuid not null references students(id),from_state interview_state,to_state interview_state not null,reason text,actor_id uuid references users(id),created_at timestamptz not null default now());
create table notifications(id uuid primary key default gen_random_uuid(),student_id uuid not null references students(id),kind text not null,message text not null,read_at timestamptz,created_at timestamptz not null default now());
create table audit_logs(id bigint generated always as identity primary key,actor_id uuid references users(id),action text not null,entity_type text not null,entity_id text not null,payload jsonb not null default '{}',created_at timestamptz not null default now());
create or replace function book_interview_slot(p_student uuid,p_slot uuid,p_attempt int,p_key text) returns interview_bookings language plpgsql security definer as $$ declare v_slot interview_slots;v_booking interview_bookings;begin select * into v_slot from interview_slots where id=p_slot for update;if not found or v_slot.status<>'OPEN' or v_slot.starts_at<=now() then raise exception 'SLOT_UNAVAILABLE';end if;if not exists(select 1 from students s where s.id=p_student and s.state in('ELIGIBLE_NOT_BOOKED','RETAKE_REQUIRED')) then raise exception 'STUDENT_NOT_ELIGIBLE';end if;insert into interview_bookings(student_id,slot_id,attempt_no,idempotency_key,status) values(p_student,p_slot,p_attempt,p_key,case when p_attempt>1 then 'RETAKE_BOOKED' else 'BOOKED' end) returning * into v_booking;update interview_slots set status='BOOKED',updated_at=now() where id=p_slot and status='OPEN';if not found then raise exception 'SLOT_RACE_LOST';end if;update students set state=case when p_attempt>1 then 'RETAKE_BOOKED' else 'BOOKED' end,updated_at=now() where id=p_student;return v_booking;exception when unique_violation then raise exception 'BOOKING_CONFLICT';end $$;
